"}, "risk_level": "R1", "schema_version": 1, "source_commit": "a04446e57ec1fbc252a871afcec7752fb2807b14", "source_math_hash": "sha256:44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a", "source_status": "CURRENT", "source_structure_hash": "sha256:3417f3e371c9ee2887e6fa3800307c96dbfc08eb191803ee7a3b7d7011f0b82a", "source_text": "These will be changed over time, but having some here now will hopefully encourage a consistent LaTeX style. We will call <QUOTEOPEN_0001>code<FOOTNOTEOPEN_0001>It is all Knuth's fault. See <CITE_0001>.<FOOTNOTECLOSE_0001><QUOTECLOSE_0001> the contents of the source files.", "source_text_hash": "sha256:8d9b6caecabe150749bbc63427ef068988c1a0a871c6f3ee41f9c5f9d8002a41", "unit_id": "tag:02BZ:p001"}
{"chapter": "coding", "node_kind": "list_item", "parent_tag": "02BZ", "placeholders": {}, "render": {"prefix": "\item ", "suffix": "
"}, "risk_level": "R1", "schema_version": 1, "source_commit": "a04446e57ec1fbc252a871afcec7752fb2807b14", "source_math_hash": "sha256:44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a", "source_status": "CURRENT", "source_structure_hash": "sha256:c1b3236178231de6fa354a8f138bc010359136f6ff55b48451a8ddcbcbe47408", "source_text": "Keep all lines in all tex files to at most 80 characters.", "source_text_hash": "sha256:569ef5e514e851d66584c8e750cd24a4ae72f465b46154a0acafe88cf9ed6f9c", "unit_id": "tag:02BZ:item001"}
{"chapter": "coding", "node_kind": "list_item", "parent_tag": "02BZ", "placeholders": {}, "render": {"prefix": "\item ", "suffix": "
"}, "risk_level": "R1", "schema_version": 1, "source_commit": "a04446e57ec1fbc252a871afcec7752fb2807b14", "source_math_hash": "sha256:44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a", "source_status": "CURRENT", "source_structure_hash": "sha256:c1b3236178231de6fa354a8f138bc010359136f6ff55b48451a8ddcbcbe47408", "source_text": "Do not use indentation in the tex file. Use syntax highlighting in your editor, instead of indentation, to visualize environments, etc.", "source_text_hash": "sha256:006439e0ca56c1c28c6a8f164de0f5bd65fc039fb7559e1d1dabf0dbba228481", "unit_id": "tag:02BZ:item002"}
{"chapter": "coding", "node_kind": "list_item", "parent_tag": "02BZ", "placeholders": {"VERBATIM_0001": "\begin{verbatim}
\medskip\noindent
\end{verbatim}", "VERBATIM_0002": "\begin{verbatim}
